async function runLearningAction(id,label,content,text,metadata){const host=$('#panelResult');host.hidden=false;host.replaceChildren();const message=document.createElement('span');message.textContent='Working…';host.append(message);try{if(id==='math.graph'&&$('#graphMode').value==='function'&&!/^\s*0+(?:\.0+)?\s*$/.test(String(text).split('=').at(-1)||''))throw new Error('Function mode graphs the left side y = f(x). It is supported here when the equation equals zero; choose equation visualization for a nonzero right side.');const value=await actions.execute(id,{selection:content,metadata,selectedContent:text});if(value?.graph){value.graph.mode=$('#graphMode').value;value.graph.title=value.graph.mode==='function'?`Function y = ${text.split('=').at(0).trim()}`:'Equation visualization: left − right = 0';value.text=value.graph.mode==='function'?`Graphing the function y = ${text.split('=').at(0).trim()}.`:`Graphing the equation by plotting its left side minus right side against y = 0.`;}showActionResult(label,value);}catch(error){showActionResult(label,{error:error.message||'This action could not be completed.'});}}
function showActionResult(label,value){const host=$('#panelResult');host.replaceChildren();host.hidden=false;const heading=document.createElement('strong');heading.textContent=label;const close=document.createElement('button');close.type='button';close.className='result-close';close.textContent='Close';close.setAttribute('aria-label','Close result');close.addEventListener('click',()=>{host.hidden=true;});const text=document.createElement('span');text.textContent=value?.error?`Could not complete: ${value.error}`:typeof value==='string'?value:value?.text||JSON.stringify(value);host.append(heading,close,text);if(value?.graph){const plot=document.createElement('canvas');plot.width=560;plot.height=300;plot.className='learning-graph';plot.setAttribute('aria-label',value.graph.title);host.append(plot);drawEquationGraph(plot,value.graph);const insert=document.createElement('button');insert.type='button';insert.textContent='Add graph to board';insert.addEventListener('click',()=>insertGraphResult(value.graph));host.append(insert);}if(value?.insertable){const insert=document.createElement('button');insert.type='button';insert.textContent='Add result to board';insert.addEventListener('click',()=>insertTextResult(value.text));host.append(insert);}}
function drawEquationGraph(canvas,coefficients){const c=canvas.getContext('2d'),{a,b,c:constant}=coefficients,w=canvas.width,h=canvas.height,xMin=-10,xMax=10,samples=160,values=Array.from({length:samples+1},(_,i)=>{const x=xMin+(xMax-xMin)*i/samples;return{x,y:a*x*x+b*x+constant};}),absMax=Math.max(5,...values.map(p=>Math.abs(p.y))),yMin=-absMax,yMax=absMax,mapX=x=>(x-xMin)/(xMax-xMin)*w,mapY=y=>h-(y-yMin)/(yMax-yMin)*h;c.fillStyle='#17221c';c.fillRect(0,0,w,h);c.strokeStyle='#405243';c.lineWidth=1;for(let x=-10;x<=10;x+=2){c.beginPath();c.moveTo(mapX(x),0);c.lineTo(mapX(x),h);c.stroke();}for(let y=Math.ceil(yMin/5)*5;y<=yMax;y+=5){c.beginPath();c.moveTo(0,mapY(y));c.lineTo(w,mapY(y));c.stroke();}c.strokeStyle='#b7c9b5';c.lineWidth=2;c.beginPath();c.moveTo(mapX(0),0);c.lineTo(mapX(0),h);c.moveTo(0,mapY(0));c.lineTo(w,mapY(0));c.stroke();c.strokeStyle='#bee09a';c.lineWidth=3;c.beginPath();values.forEach((p,i)=>i?c.lineTo(mapX(p.x),mapY(p.y)):c.moveTo(mapX(p.x),mapY(p.y)));c.stroke();c.fillStyle='#d6e4d3';c.font='14px system-ui';c.fillText('x',w-18,mapY(0)-8);c.fillText('y',mapX(0)+8,16);c.fillText(coefficients.title||'y = f(x)',10,18);}
function insertGraphResult(graph){const bounds=selection.selectedContent(doc).bounds,object={id:crypto.randomUUID(),type:'graph',x:(bounds?.maxX||80)+30,y:bounds?.minY||80,width:420,height:260,color:'#bee09a',strokeWidth:2,metadata:{graph:{a:graph.a,b:graph.b,c:graph.c,mode:graph.mode,title:graph.title}}};objectManager.add(doc,object);commit();tell('Graph added to board.');}
engine.registerObjectRenderer('graph',(c,o)=>{const graph=o.metadata?.graph;if(!graph)return;const {a,b,c:constant}=graph,w=o.width,h=o.height,xMin=-10,xMax=10,points=Array.from({length:121},(_,i)=>{const x=xMin+(xMax-xMin)*i/120;return{x,y:a*x*x+b*x+constant};}),extent=Math.max(5,...points.map(p=>Math.abs(p.y))),mapX=x=>o.x+(x-xMin)/(xMax-xMin)*w,mapY=y=>o.y+h-(y+extent)/(2*extent)*h;c.save();c.fillStyle='#17221c';c.fillRect(o.x,o.y,w,h);c.strokeStyle='#405243';c.lineWidth=1;c.strokeRect(o.x,o.y,w,h);for(let x=-10;x<=10;x+=2){c.beginPath();c.moveTo(mapX(x),o.y);c.lineTo(mapX(x),o.y+h);c.stroke();}c.beginPath();c.moveTo(o.x,mapY(0));c.lineTo(o.x+w,mapY(0));c.moveTo(mapX(0),o.y);c.lineTo(mapX(0),o.y+h);c.stroke();c.strokeStyle='#bee09a';c.lineWidth=2;c.beginPath();points.forEach((p,i)=>i?c.lineTo(mapX(p.x),mapY(p.y)):c.moveTo(mapX(p.x),mapY(p.y)));c.stroke();c.fillStyle='#d6e4d3';c.font='12px system-ui';c.fillText(graph.title||'Graph',o.x+8,o.y+16);c.restore();});
function insertTextResult(text){const bounds=selection.selectedContent(doc).bounds,object={id:crypto.randomUUID(),type:'text',x:(bounds?.maxX||80)+30,y:bounds?.minY||80,width:280,height:52,text:String(text).slice(0,1000),color:'#f4f2e8',fontSize:20,strokeWidth:width,metadata:{}};objectManager.add(doc,object);commit();engine.render();bus.emit('object:created',{documentId:doc.id,objectId:object.id,type:'text'});tell('Result added to board.');}
function selectedStrokeKey(content){return JSON.stringify({documentId:content.documentId,strokes:content.strokes.map(s=>[s.id,s.points])});}
function createHandwritingCrop(content){const bounds=content.bounds;if(!bounds||(!content.strokes.length&&!content.objects.length))throw new Error('Select board content before sending it to Gemini.');const span=Math.max(bounds.maxX-bounds.minX,bounds.maxY-bounds.minY,1),margin=Math.max(14,Math.min(48,span*.12)),left=bounds.minX-margin,top=bounds.minY-margin,w=bounds.maxX-bounds.minX+margin*2,h=bounds.maxY-bounds.minY+margin*2,scale=Math.min(4,2400/Math.max(w,h),Math.sqrt(12_000_000/(w*h))),output=document.createElement('canvas');output.width=Math.max(1,Math.ceil(w*scale));output.height=Math.max(1,Math.ceil(h*scale));const c=output.getContext('2d',{alpha:false});c.fillStyle='#f5f4ec';c.fillRect(0,0,output.width,output.height);c.setTransform(scale,0,0,scale,-left*scale,-top*scale);c.lineCap='round';c.lineJoin='round';for(const stroke of content.strokes){if(!stroke.points.length)continue;c.strokeStyle='#17251d';c.lineWidth=Math.max(1.2,stroke.width);c.beginPath();c.moveTo(stroke.points[0].x,stroke.points[0].y);if(stroke.points.length===1)c.lineTo(stroke.points[0].x+.2,stroke.points[0].y+.2);else for(let i=1;i<stroke.points.length;i++){const p=stroke.points[i],prev=stroke.points[i-1];c.quadraticCurveTo(prev.x,prev.y,(prev.x+p.x)/2,(prev.y+p.y)/2);}const end=stroke.points.at(-1);if(stroke.points.length>1)c.lineTo(end.x,end.y);c.stroke();}for(const object of content.objects){if(object.type==='text'){c.fillStyle='#17251d';c.font=`${object.fontSize||22}px system-ui,sans-serif`;c.textBaseline='top';c.fillText(object.text,object.x,object.y);}else if(['line','arrow','rect','ellipse'].includes(object.type)){c.strokeStyle='#17251d';c.lineWidth=object.strokeWidth||3;c.strokeRect(object.x,object.y,object.width,object.height);}}return output;}
