canvas.addEventListener('pointermove',e=>{const p=engine.toBoard(e);if(drawing?.kind==='stroke'){const pts=drawing.item.points,last=pts[pts.length-1];if(Math.hypot(p.x-last.x,p.y-last.y)>.7){pts.push(p);engine.drawLiveSegment(drawing.item,last,p);}}else if(drawing?.kind==='shape'){const o=drawing.item;o.width=p.x-drawing.start.x;o.height=p.y-drawing.start.y;engine.drawPreview(o);}else if(drag?.kind==='pan'){engine.pan={x:drag.px+(e.clientX-drag.sx),y:drag.py+(e.clientY-drag.sy)};engine.render();}else if(drag?.kind==='move'){const dx=p.x-drag.start.x,dy=p.y-drag.start.y;for(const[id,o]of drag.originalObjects){const dest=doc.objects.find(x=>x.id===id);Object.assign(dest,o,{x:o.x+dx,y:o.y+dy});}for(const[id,s]of drag.originalStrokes){const dest=doc.strokes.find(x=>x.id===id);dest.points=s.points.map(pt=>({...pt,x:pt.x+dx,y:pt.y+dy}));}engine.render();}else if(drag?.kind==='resize'){resizeSelection(drag,p);engine.render();}else if(marquee){marquee.current=p;updateMarquee();}});
