$('#zoomIn').onclick=()=>engine.setZoom(engine.zoom*1.15);$('#zoomOut').onclick=()=>engine.setZoom(engine.zoom/1.15);$('#zoomReset').onclick=()=>{engine.zoom=1;engine.pan={x:0,y:0};engine.render();engine.onChange();};canvas.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();const r=canvas.getBoundingClientRect();engine.setZoom(engine.zoom*(e.deltaY<0?1.08:.92),{x:e.clientX-r.left,y:e.clientY-r.top});}},{passive:false});
