$('#analyzeSelection').addEventListener('click',analyzeSelectedContent);$('#requestedFormat').addEventListener('change',()=>{learningAnalysis=null;renderLearningPanel(selection.selectedContent(doc));});
$('#recognizedCorrection').addEventListener('change',e=>{handwritingCorrection=e.target.value.trim().slice(0,1000);handwritingConfirmed=true;learningAnalysis=null;renderContextActions(selection.selectedContent(doc));});
$('#askSelection').addEventListener('click',async()=>{const question=$('#customQuestion').value.trim(),content=selection.selectedContent(doc);if(!content.itemIds.length){$('#questionStatus').textContent='Select content first.';return;}if(!question){$('#questionStatus').textContent='Enter a question about the selection.';return;}const sequence=handwritingSequence;$('#askSelection').disabled=true;$('#questionStatus').textContent='Asking Gemini…';try{if(!auth.currentUser)throw new Error('Sign in to ask a question.');const token=await auth.currentUser.getIdToken(),text=content.objects.filter(o=>o.type==='text').map(o=>o.text).join('\n').trim(),body={selectedText:text,subject:handwritingRecognition?.result?.subject||'unknown',requestedFormat:'explanation',customQuestion:question,selection:{id:crypto.randomUUID(),strokeIds:content.strokeIds,objectIds:content.objectIds,bounds:content.bounds,objectTypes:content.objects.map(o=>o.type)}};if(content.strokes.length||content.objects.some(o=>o.type!=='text')||!text){const crop=createHandwritingCrop(content),url=crop.toDataURL('image/png');body.imageBase64=url.slice(url.indexOf(',')+1);body.mimeType='image/png';}const response=await fetch(`${boardApiBase()}/api/blackboard/analyze-selection`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`},credentials:'include',cache:'no-store',body:JSON.stringify(body)}),payload=await response.json();if(!response.ok)throw new Error(payload.error||'Question failed.');if(sequence!==handwritingSequence)return;learningAnalysis=payload.result;showActionResult('Answer',payload.result.explanation||'Gemini returned no answer.');$('#questionStatus').textContent='';}catch(error){if(sequence===handwritingSequence)$('#questionStatus').textContent=error.message||'Could not answer this question.';}finally{$('#askSelection').disabled=false;}});
$('#exportJson').onclick=()=>download(new Blob([persistence.serialize(doc)],{type:'application/json'}),`${safeName()}-board.json`);$('#importJson').onclick=()=>$('#importFile').click();$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10_000_000)throw new Error('Board file is larger than 10 MB.');const next=persistence.restore(await file.text());history.push(doc);applyDocument(next);tell('Board restored.');}catch(err){tell(err.message);}finally{e.target.value='';}});
function safeName(){return(doc.title||'blackboard').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'blackboard';}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('#exportPng').onclick=()=>{const items=[...doc.strokes,...doc.objects],b=worldBounds(items),out=document.createElement('canvas');out.width=Math.min(10000,Math.max(1,Math.ceil(b.width+80)));out.height=Math.min(10000,Math.max(1,Math.ceil(b.height+80)));const c=out.getContext('2d');c.fillStyle='#294333';c.fillRect(0,0,out.width,out.height);c.save();c.translate(40-b.x,40-b.y);const original=engine.ctx;engine.ctx=c;doc.strokes.forEach(s=>engine.drawStroke(s));doc.objects.forEach(o=>engine.drawObject(o));engine.ctx=original;c.restore();out.toBlob(blob=>blob&&download(blob,`${safeName()}.png`));};
function refreshLibrary(){const select=$('#boardLibrary');if(!select)return;const active=doc.id,boards=persistence.list();select.replaceChildren(new Option('Saved boards',''));for(const b of boards){const option=new Option(`${b.title} · ${new Date(b.updatedAt).toLocaleDateString()}`,b.id);if(b.id===active)option.selected=true;select.add(option);}}
$('#boardLibrary').addEventListener('change',e=>{if(!e.target.value)return;try{clearTimeout(saveTimer);persistence.save(doc);const next=persistence.activate(e.target.value);doc=next;lastCommitted=clone(doc);history.clear();$('#boardTitle').value=doc.title;engine.selected.clear();announceSelection('board:opened');render();refreshLibrary();tell('Board opened.');}catch(err){status.textContent='Save failed';status.className='save-status error';refreshLibrary();tell(err.message);}});
function restore(){try{const old=persistence.load();if(old){doc=old;lastCommitted=clone(doc);$('#boardTitle').value=doc.title;status.textContent='Saved';}}catch(e){status.textContent='Restore failed';status.className='save-status error';tell(e.message);}refreshLibrary();}
window.addEventListener('beforeunload',()=>{clearTimeout(saveTimer);try{persistence.save(doc);}catch{}});
registerContextActions();exposeSelectionAPI();restore();frame.dataset.tool=tool;render();announceSelection('ready');
